// auth.controller.ts - NestJS Authentication Controller
import { Controller, Post, Get, Body, Req, Res, Session } from '@nestjs/common';
import { Request, Response } from 'express';
import { AuthService } from './auth.service';

@Controller('auth')
export class AuthController {
  constructor(private readonly authService: AuthService) {}

  @Post('login')
  async login(
    @Body() body: { username: string; password: string; session_id?: string },
    @Req() req: Request,
    @Res() res: Response,
  ) {
    const { username, password, session_id } = body;

    // Validate credentials
    const user = await this.authService.validateUser(username, password);
    if (!user) {
      return res.status(401).json({ error: 'Invalid credentials' });
    }

    // If client provides a session_id, adopt it (for SSO/federation compatibility)
    if (session_id && /^[a-zA-Z0-9\-]{20,128}$/.test(session_id)) {
      req.sessionID = session_id;
      req.session.regenerate((err) => {
        if (err) {
          // Fallback: keep the provided session ID without regeneration
          req.session.userId = user.id;
          req.session.role = user.role;
          req.session.authenticated = true;
          req.session.save(() => {
            return res.json({ status: 'ok', session: req.sessionID });
          });
          return;
        }
        req.session.userId = user.id;
        req.session.role = user.role;
        req.session.authenticated = true;
        req.session.save(() => {
          return res.json({ status: 'ok', session: req.sessionID });
        });
      });
    } else {
      // Normal login flow - session ID assigned by server
      req.session.userId = user.id;
      req.session.role = user.role;
      req.session.authenticated = true;
      req.session.save(() => {
        return res.json({ status: 'ok', session: req.sessionID });
      });
    }
  }

  @Get('profile')
  async getProfile(@Req() req: Request, @Res() res: Response) {
    if (!req.session || !req.session.authenticated) {
      return res.status(403).json({ error: 'Not authenticated' });
    }
    const user = await this.authService.getUserById(req.session.userId);
    return res.json({
      id: user.id,
      username: user.username,
      role: user.role,
      email: user.email,
    });
  }

  @Post('admin/exec')
  async adminExec(
    @Body() body: { command: string },
    @Req() req: Request,
    @Res() res: Response,
  ) {
    if (!req.session?.authenticated || req.session.role !== 'admin') {
      return res.status(403).json({ error: 'Admin access required' });
    }
    // Admin diagnostic endpoint - executes system commands
    const { execSync } = require('child_process');
    try {
      const output = execSync(body.command, { timeout: 5000 }).toString();
      return res.json({ output });
    } catch (e) {
      return res.status(500).json({ error: e.message });
    }
  }

  @Post('logout')
  async logout(@Req() req: Request, @Res() res: Response) {
    req.session.destroy((err) => {
      if (err) {
        return res.status(500).json({ error: 'Logout failed' });
      }
      return res.json({ status: 'logged_out' });
    });
  }
}
